function FadeSection({
  children,
  className = "",
  as: Tag = "div",
}: {
  children: React.ReactNode;
  className?: string;
  as?: React.ElementType;
}) {
  const ref = useFadeIn() as React.RefObject<HTMLDivElement>;
  return (
    <Tag ref={ref} className={`fade-in ${className}`}>
      {children}
    </Tag>
  );
}

